//! Decodes the protocol revision 2 vectors in `tests/vectors/`.
//!
//! `rev2-server-vectors.json` is generated by an independent Python
//! implementation of the Rev2 byte layouts (`gen_rev2_vectors.py`).
use crate::{records, settings, stream};
use serde_json::{json, Value};

fn vectors() -> Value {
    serde_json::from_str(include_str!("../tests/vectors/rev2-server-vectors.json")).unwrap()
}

fn hex(text: &str) -> Vec<u8> {
    stream::hex_decode(text.as_bytes()).expect("vector hex")
}

/// Looks up a dotted path in a JSON value.
fn at<'a>(value: &'a Value, path: &str) -> &'a Value {
    path.split('.').fold(value, |value, key| &value[key])
}

fn same(actual: &Value, expected: &Value) -> bool {
    match (actual.as_f64(), expected.as_f64()) {
        (Some(a), Some(e)) => (a - e).abs() < 1e-9,
        _ => actual == expected,
    }
}

#[test]
fn every_record_vector_decodes_to_its_expected_fields() {
    let vectors = vectors();
    let records_list = vectors["records"].as_array().unwrap();
    let mut types = std::collections::BTreeSet::new();
    for vector in records_list {
        let name = vector["name"].as_str().unwrap();
        let (frames, issues) = stream::split_frames(&hex(vector["frame_hex"].as_str().unwrap()));
        assert!(issues.is_empty(), "{name}: {issues:?}");
        assert_eq!(frames.len(), 1, "{name}");
        let frame = &frames[0];
        assert_eq!(
            u64::from(frame.record_type),
            vector["type"].as_u64().unwrap()
        );
        assert_eq!(u64::from(frame.seq), vector["seq"].as_u64().unwrap());
        let record = records::decode(frame.record_type, &frame.payload)
            .unwrap_or_else(|e| panic!("{name}: {e}"));
        let json = serde_json::to_value(&record).unwrap();
        for (path, expected) in vector["expect"].as_object().unwrap() {
            let actual = at(&json, path);
            assert!(
                same(actual, expected),
                "{name}: {path} decoded {actual} expected {expected} ({json})"
            );
        }
        types.insert(frame.record_type);
    }
    // Every defined type 0..=21 is covered by at least one vector.
    for record_type in 0..=21u8 {
        assert!(
            types.contains(&record_type),
            "no vector for type {record_type}"
        );
    }
}

#[test]
fn batch_vectors_verify_crc_and_split_frames() {
    for vector in vectors()["batches"].as_array().unwrap() {
        let name = vector["name"].as_str().unwrap();
        let expect = &vector["expect"];
        let payload = match vector["mqtt_payload"].as_str() {
            Some(text) => text.as_bytes().to_vec(),
            None => hex(vector["payload_hex"].as_str().unwrap()),
        };
        let (bytes, encoding) = stream::decode_payload(&payload, stream::BATCH_MAGIC).unwrap();
        assert_eq!(
            encoding.as_str(),
            vector["encoding"].as_str().unwrap(),
            "{name}"
        );
        let parsed = stream::parse_batch(&bytes);
        if expect["ok"] == false {
            let error = parsed.expect_err(name);
            assert_eq!(error.code(), expect["error"].as_str().unwrap(), "{name}");
            continue;
        }
        let batch = parsed.unwrap_or_else(|e| panic!("{name}: {e}"));
        let seqs: Vec<u64> = batch.frames.iter().map(|f| u64::from(f.seq)).collect();
        let expected: Vec<u64> = expect["frame_seqs"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_u64().unwrap())
            .collect();
        assert_eq!(seqs, expected, "{name}");
        if let Some(log_id) = expect["log_id"].as_u64() {
            assert_eq!(u64::from(batch.header.log_id), log_id);
        }
        if let Some(start) = expect["start_pos"].as_u64() {
            assert_eq!(batch.frames[0].pos.map(u64::from), Some(start));
        }
        if expect["resend"] == true {
            assert!(batch.header.resend());
        }
        let codes: Vec<&str> = batch.issues.iter().map(|i| i.code).collect();
        let expected_codes: Vec<&str> = expect["issues"]
            .as_array()
            .map(|a| a.iter().map(|v| v.as_str().unwrap()).collect())
            .unwrap_or_default();
        assert_eq!(codes, expected_codes, "{name}");
        // Every decoded frame also decodes as a typed record.
        for frame in &batch.frames {
            records::decode(frame.record_type, &frame.payload)
                .unwrap_or_else(|e| panic!("{name} seq {}: {e}", frame.seq));
        }
    }
}

#[test]
fn file_chunk_and_tlv_vectors_decode() {
    let vectors = vectors();
    for vector in vectors["file_chunks"].as_array().unwrap() {
        let chunk =
            stream::parse_file_chunk(&hex(vector["payload_hex"].as_str().unwrap())).unwrap();
        let expect = &vector["expect"];
        assert_eq!(
            u64::from(chunk.command_id),
            expect["command_id"].as_u64().unwrap()
        );
        assert_eq!(u64::from(chunk.offset), expect["offset"].as_u64().unwrap());
        assert_eq!(
            u64::from(chunk.total_size),
            expect["total_size"].as_u64().unwrap()
        );
        assert_eq!(
            stream::hex_encode(&chunk.data),
            expect["data_hex"].as_str().unwrap()
        );
    }
    let decoded = settings::decode_tlv(&hex(vectors["tlv"]["payload_hex"].as_str().unwrap()));
    assert!(decoded.warnings.is_empty());
    let effective = decoded.effective();
    for (key, expected) in vectors["tlv"]["expect"].as_object().unwrap() {
        assert!(same(&effective[key], expected), "{key}: {}", effective[key]);
    }
}

// ---------------------------------------------------------------------------
// Golden vectors written by the firmware team (copied unchanged into
// tests/vectors/firmware/; provenance in tests/vectors/firmware/README.md).

fn firmware(name: &str) -> Value {
    let text = match name {
        "records" => include_str!("../tests/vectors/firmware/rev2-records.json"),
        "batches" => include_str!("../tests/vectors/firmware/rev2-batches.json"),
        _ => include_str!("../tests/vectors/firmware/rev2-json.json"),
    };
    serde_json::from_str(text).unwrap()
}

/// The decoded record expressed in the firmware vectors' raw field names
/// (sentinels restored, scaled values back to integers).
fn firmware_fields(record: &records::Record) -> serde_json::Map<String, Value> {
    use records::Record as R;
    let mut map = serde_json::Map::new();
    let mut put = |key: &str, value: Value| {
        map.insert(key.to_owned(), value);
    };
    let time = |put: &mut dyn FnMut(&str, Value), t: records::TimeBlock| {
        put("time", json!(t.time));
        put("time_flags", json!(t.flags));
    };
    let sensor = |put: &mut dyn FnMut(&str, Value), s: records::SensorBlock| {
        put("sensor_mV", json!(s.sensor_mv.unwrap_or(0xFFFF)));
        put("level", json!(s.level_milli.unwrap_or(i32::MIN)));
        put("sensor_status", json!(s.sensor_status));
    };
    let i16v = |v: Option<i16>| json!(v.unwrap_or(i16::MIN));
    match record.clone() {
        R::Routine {
            sample_index,
            sensor: s,
        } => {
            put("sample_index", json!(sample_index));
            sensor(&mut put, s);
        }
        R::Timestamped {
            time: t,
            settings_gen,
            reason,
            flags,
            interval_s,
            sensor: s,
        } => {
            time(&mut put, t);
            put("settings_gen", json!(settings_gen));
            put("reason", json!(reason));
            put("flags", json!(flags));
            put("interval_s", json!(interval_s));
            sensor(&mut put, s);
        }
        R::Position {
            time: t,
            settings_gen,
            reason,
            fix,
            lat,
            lon,
            alt_m,
            hdop,
            satellites,
            accel_x_mg,
            accel_y_mg,
            accel_z_mg,
            accel_status,
        } => {
            time(&mut put, t);
            put("settings_gen", json!(settings_gen));
            put("reason", json!(reason));
            put("fix", json!(fix));
            put(
                "lat_e7",
                json!(lat
                    .map(|v| (v * 1e7).round() as i64)
                    .unwrap_or(i64::from(i32::MIN))),
            );
            put(
                "lon_e7",
                json!(lon
                    .map(|v| (v * 1e7).round() as i64)
                    .unwrap_or(i64::from(i32::MIN))),
            );
            put("alt_m", i16v(alt_m));
            put(
                "hdop_x10",
                json!(hdop.map(|v| (v * 10.0).round() as i64).unwrap_or(255)),
            );
            put("satellites", json!(satellites));
            put("accel_x_mg", i16v(accel_x_mg));
            put("accel_y_mg", i16v(accel_y_mg));
            put("accel_z_mg", i16v(accel_z_mg));
            put("accel_status", json!(accel_status));
        }
        R::Snapshot {
            settings_gen,
            settings_schema,
            fragment_index,
            fragment_count,
            total_len,
            snapshot_crc32,
            data,
            ..
        } => {
            put("settings_gen", json!(settings_gen));
            put("settings_schema", json!(settings_schema));
            put("fragment_index", json!(fragment_index));
            put("fragment_count", json!(fragment_count));
            put("total_len", json!(total_len));
            put("snapshot_crc32", json!(snapshot_crc32));
            put("data", json!(stream::hex_encode(&data)));
        }
        R::Test {
            time: t,
            settings_gen,
            trigger,
            req_id,
            battery_mv,
            solar_mv,
            csq,
            sensor: s,
            status,
        } => {
            time(&mut put, t);
            put("settings_gen", json!(settings_gen));
            put("trigger", json!(trigger));
            put("req_id", json!(req_id));
            put("battery_mV", json!(battery_mv.unwrap_or(0xFFFF)));
            put("solar_mV", json!(solar_mv.unwrap_or(0xFFFF)));
            put("csq", json!(csq.unwrap_or(99)));
            sensor(&mut put, s);
            put("status", json!(status));
        }
        R::SdFlush {
            time: t,
            saved_end,
            last_seq_saved,
            segment_no,
        } => {
            time(&mut put, t);
            put("saved_end", json!(saved_end));
            put("last_seq_saved", json!(last_seq_saved));
            put("segment_no", json!(segment_no));
        }
        R::MqttFlush {
            time: t,
            saved_end,
            last_seq_saved,
            batch_count,
        } => {
            time(&mut put, t);
            put("saved_end", json!(saved_end));
            put("last_seq_saved", json!(last_seq_saved));
            put("batch_count", json!(batch_count));
        }
        R::Alarm {
            time: t,
            settings_gen,
            limit,
            level_milli,
            threshold_milli,
            ..
        } => {
            time(&mut put, t);
            put("settings_gen", json!(settings_gen));
            put("limit", json!(limit));
            put("level", json!(level_milli.unwrap_or(i32::MIN)));
            put("threshold", json!(threshold_milli.unwrap_or(i32::MIN)));
        }
        R::GpsMoved {
            time: t,
            distance_m,
            threshold_m,
        } => {
            time(&mut put, t);
            put("distance_m", json!(distance_m));
            put("threshold_m", json!(threshold_m));
        }
        R::Impact {
            time: t,
            source,
            peak_mg,
        } => {
            time(&mut put, t);
            put("source", json!(source));
            put("peak_mg", json!(peak_mg.unwrap_or(0xFFFF)));
        }
        R::Orientation {
            time: t,
            tilt_change,
        } => {
            time(&mut put, t);
            put("tilt_change_x10", json!(tilt_change));
        }
        R::TailLock {
            time: t,
            head,
            tail,
            sd_saved_end,
            mqtt_saved_end,
            reason,
        } => {
            time(&mut put, t);
            put("head", json!(head));
            put("tail", json!(tail));
            put("sd_saved_end", json!(sd_saved_end));
            put("mqtt_saved_end", json!(mqtt_saved_end));
            put("reason", json!(reason));
        }
        R::LogStart {
            time: t,
            log_id,
            previous_log_id,
            reason,
            firmware_version,
            envelope_version,
            payload_schema,
            settings_gen,
            mcu_uid,
        } => {
            time(&mut put, t);
            put("log_id", json!(log_id));
            put("previous_log_id", json!(previous_log_id));
            put("reason", json!(reason));
            put(
                "firmware_version",
                json!(u32::from_le_bytes(firmware_version)),
            );
            put("envelope_version", json!(envelope_version));
            put("payload_schema", json!(payload_schema));
            put("settings_gen", json!(settings_gen));
            put("mcu_uid", json!(mcu_uid));
        }
        R::ClockSet {
            old,
            new_time,
            new_flags,
            uptime_s,
        } => {
            time(&mut put, old);
            put("new_time", json!(new_time));
            put("new_time_flags", json!(new_flags));
            put("uptime_s", json!(uptime_s));
        }
        R::DataGap {
            start,
            gap_end,
            missed_readings,
            missed_events,
            reason,
        } => {
            time(&mut put, start);
            put("gap_end", json!(gap_end));
            put("missed_readings", json!(missed_readings));
            put("missed_events", json!(missed_events));
            put("reason", json!(reason));
        }
        R::SensorFault {
            time: t,
            settings_gen,
            state,
            sensor_status,
            sensor_mv,
        } => {
            time(&mut put, t);
            put("settings_gen", json!(settings_gen));
            put("state", json!(state));
            put("sensor_status", json!(sensor_status));
            put("sensor_mV", json!(sensor_mv.unwrap_or(0xFFFF)));
        }
        R::PowerCritical {
            time: t,
            kind,
            battery_mv,
            solar_mv,
        } => {
            time(&mut put, t);
            put("kind", json!(kind));
            put("battery_mV", json!(battery_mv.unwrap_or(0xFFFF)));
            put("solar_mV", json!(solar_mv.unwrap_or(0xFFFF)));
        }
        R::StorageWarning {
            time: t,
            kind,
            unsaved_bytes,
            usable_bytes,
        } => {
            time(&mut put, t);
            put("kind", json!(kind));
            put("unsaved_bytes", json!(unsaved_bytes));
            put("usable_bytes", json!(usable_bytes));
        }
        R::TailUnlocked {
            time: t,
            new_tail,
            sd_saved_end,
            mqtt_saved_end,
            locked_seconds,
        } => {
            time(&mut put, t);
            put("new_tail", json!(new_tail));
            put("sd_saved_end", json!(sd_saved_end));
            put("mqtt_saved_end", json!(mqtt_saved_end));
            put("locked_seconds", json!(locked_seconds));
        }
        R::Tilt {
            time: t,
            settings_gen,
            reason,
            accel_x_mg,
            accel_y_mg,
            accel_z_mg,
            pitch_decideg,
            roll_decideg,
            accel_status,
        } => {
            time(&mut put, t);
            put("settings_gen", json!(settings_gen));
            put("reason", json!(reason));
            put("accel_x_mg", i16v(accel_x_mg));
            put("accel_y_mg", i16v(accel_y_mg));
            put("accel_z_mg", i16v(accel_z_mg));
            put("pitch_x10", i16v(pitch_decideg));
            put("roll_x10", i16v(roll_decideg));
            put("accel_status", json!(accel_status));
        }
        R::Reserved { .. } | R::BenchOnly { .. } => {}
    }
    map
}

#[test]
fn firmware_record_vectors_decode_field_for_field() {
    let vectors = firmware("records");
    let mut types = std::collections::BTreeSet::new();
    let mut tlvs = 0;
    for vector in vectors.as_array().unwrap() {
        match vector["kind"].as_str().unwrap() {
            "record" => {
                let note = vector["note"].as_str().unwrap();
                let (frames, issues) =
                    stream::split_frames(&hex(vector["frame_hex"].as_str().unwrap()));
                assert!(issues.is_empty(), "{note}: {issues:?}");
                let frame = &frames[0];
                assert_eq!(
                    u64::from(frame.record_type),
                    vector["type"].as_u64().unwrap()
                );
                assert_eq!(u64::from(frame.seq), vector["seq"].as_u64().unwrap());
                assert_eq!(
                    frame.payload.len() as u64,
                    vector["payload_len"].as_u64().unwrap()
                );
                let record = records::decode(frame.record_type, &frame.payload)
                    .unwrap_or_else(|e| panic!("{note}: {e}"));
                let decoded = firmware_fields(&record);
                for (key, expected) in vector["fields"].as_object().unwrap() {
                    let actual = decoded
                        .get(key)
                        .unwrap_or_else(|| panic!("{note}: no field {key}"));
                    let equal = match (actual, expected) {
                        (Value::String(a), Value::String(e)) => a.eq_ignore_ascii_case(e),
                        _ => same(actual, expected),
                    };
                    assert!(equal, "{note}: {key} decoded {actual} expected {expected}");
                }
                types.insert(frame.record_type);
            }
            "settings_tlv" => {
                let note = vector["note"].as_str().unwrap();
                let tlv = hex(vector["tlv_hex"].as_str().unwrap());
                assert_eq!(
                    format!("{:08X}", crate::crc::crc32(&tlv)),
                    vector["crc32"].as_str().unwrap()
                );
                let decoded = settings::decode_tlv(&tlv);
                assert!(
                    decoded.warnings.is_empty(),
                    "{note}: {:?}",
                    decoded.warnings
                );
                let effective = decoded.effective();
                for (key, expected) in vector["settings"].as_object().unwrap() {
                    let actual = &effective[key];
                    let equal = match (actual.as_array(), expected.as_array()) {
                        (Some(a), Some(e)) => {
                            a.len() == e.len() && a.iter().zip(e).all(|(a, e)| same(a, e))
                        }
                        _ => same(actual, expected),
                    };
                    assert!(equal, "{note}: {key} decoded {actual} expected {expected}");
                }
                tlvs += 1;
            }
            "meta" => {
                assert_eq!(vector["envelope_version"], 1);
                assert_eq!(vector["payload_schema"], 1);
                assert_eq!(
                    format!("{:02X}", crate::crc::crc8_autosar(b"123456789")),
                    vector["crc8_autosar_123456789"].as_str().unwrap()
                );
            }
            other => panic!("unknown vector kind {other}"),
        }
    }
    assert!(tlvs >= 3);
    for record_type in 0..=21u8 {
        assert!(
            types.contains(&record_type),
            "no firmware vector for type {record_type}"
        );
    }
}

/// Rev2 lists Type 14 `firmware_version` as "u32 (major, minor, patch,
/// build bytes)"; the firmware stores `major<<16 | minor<<8 | patch` with
/// the build in bits 24-31. The server keeps the raw u32 and reads it the
/// firmware's way; this pins that choice until the contract is clarified.
#[test]
fn firmware_version_follows_the_firmware_packing() {
    assert_eq!(records::firmware_version_text([0, 2, 2, 0]), "2.2.0");
    assert_eq!(records::firmware_version_raw([0, 2, 2, 0]), 0x0002_0200);
}

#[test]
fn firmware_batch_vectors_decode() {
    for vector in firmware("batches")["vectors"].as_array().unwrap() {
        let name = vector["name"].as_str().unwrap();
        let payload = match vector["payload_text"].as_str() {
            Some(text) => text.as_bytes().to_vec(),
            None => hex(vector["payload_hex"].as_str().unwrap()),
        };
        let channel = vector["channel"].as_str().unwrap();
        assert!(crate::rev2::is_rev2_payload(channel, &payload), "{name}");
        let magic = if channel == "data/file" {
            stream::FILE_MAGIC
        } else {
            stream::BATCH_MAGIC
        };
        let (bytes, encoding) = stream::decode_payload(&payload, magic).unwrap();
        assert_eq!(
            encoding.as_str(),
            if vector["encoding"] == "hex" {
                "hex"
            } else {
                "bin"
            },
            "{name}"
        );
        assert_eq!(
            payload.len() as u64,
            vector["length"].as_u64().unwrap(),
            "{name}"
        );
        let expect = &vector["expect"];
        if channel == "data/file" {
            let chunk = stream::parse_file_chunk(&bytes).unwrap_or_else(|e| panic!("{name}: {e}"));
            assert_eq!(
                u64::from(chunk.command_id),
                expect["cmd_id"].as_u64().unwrap()
            );
            assert_eq!(u64::from(chunk.offset), expect["offset"].as_u64().unwrap());
            assert_eq!(
                u64::from(chunk.total_size),
                expect["total"].as_u64().unwrap()
            );
            assert_eq!(
                stream::hex_encode(&chunk.data),
                expect["data"].as_str().unwrap()
            );
            assert_eq!(
                format!("{:08X}", crate::crc::crc32(&chunk.data)),
                expect["data_crc32"].as_str().unwrap()
            );
            continue;
        }
        let parsed = stream::parse_batch(&bytes);
        if vector["valid"] == false {
            let error = parsed.expect_err(name);
            assert_eq!(error.code(), "bad-crc32", "{name} ({})", vector["error"]);
            continue;
        }
        let batch = parsed.unwrap_or_else(|e| panic!("{name}: {e}"));
        let h = batch.header;
        for (key, actual) in [
            ("header_len", u64::from(h.header_len)),
            ("envelope_version", u64::from(h.envelope_version)),
            ("payload_schema", u64::from(h.payload_schema)),
            ("log_id", u64::from(h.log_id)),
            ("first_seq", u64::from(h.first_seq)),
            ("last_seq", u64::from(h.last_seq)),
            ("start_pos", u64::from(h.start_pos)),
            ("end_pos", u64::from(h.end_pos)),
            ("frame_count", u64::from(h.frame_count)),
            ("flags", u64::from(h.flags)),
            ("bad_frames", batch.issues.len() as u64),
        ] {
            assert_eq!(actual, expect[key].as_u64().unwrap(), "{name}: {key}");
        }
        assert!(batch.positions_valid, "{name}");
        assert!(batch.warnings.is_empty(), "{name}: {:?}", batch.warnings);
        let good: Vec<&Value> = vector["frames"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|f| f["crc8_ok"] == true)
            .collect();
        assert_eq!(batch.frames.len(), good.len(), "{name}");
        for (frame, expected) in batch.frames.iter().zip(good) {
            assert_eq!(
                u64::from(frame.seq),
                expected["seq"].as_u64().unwrap(),
                "{name}"
            );
            assert_eq!(
                u64::from(frame.record_type),
                expected["type"].as_u64().unwrap()
            );
            assert_eq!(
                stream::hex_encode(&frame.raw),
                expected["frame"].as_str().unwrap()
            );
        }
    }
}

#[test]
fn firmware_json_vectors_parse_and_envelopes_match() {
    let vectors = firmware("json");
    for uplink in vectors["uplink"].as_array().unwrap() {
        let name = uplink["name"].as_str().unwrap();
        let channel = uplink["channel"].as_str().unwrap();
        let payload = uplink["payload"].as_str().unwrap().as_bytes();
        assert!(crate::rev2::is_rev2_payload(channel, payload), "{name}");
        let object = crate::rev2::object(payload).unwrap();
        match channel {
            "status" => {
                crate::rev2::parse_status(&object).unwrap_or_else(|e| panic!("{name}: {e}"));
            }
            "health" => assert!(
                crate::rev2::parse_health(&object).bat_mv.is_some(),
                "{name}"
            ),
            "alerts" => assert!(
                crate::rev2_store::alert_event_name(&object).is_some(),
                "{name}"
            ),
            "info" => assert_eq!(object["proto"], 2),
            "test/result" | "reading" | "gps" => assert!(object.contains_key("t"), "{name}"),
            other => panic!("{name}: unexpected uplink channel {other}"),
        }
    }
    let mut envelopes = 0;
    for case in vectors["downlink"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        for step in case["steps"].as_array().unwrap() {
            let now = step["now"]["t"].as_i64().unwrap();
            for message in step["in"].as_array().unwrap() {
                let text = message["payload"].as_str().unwrap();
                let Ok(parsed) = serde_json::from_str::<Value>(text) else {
                    continue; // deliberately malformed
                };
                let (Some(id), Some(exp), Some(op), Some(2)) = (
                    parsed["id"].as_i64(),
                    parsed["exp"].as_i64(),
                    parsed["op"].as_str(),
                    parsed["v"].as_i64(),
                ) else {
                    continue;
                };
                // The server builds byte-for-byte the same JSON value.
                let args = parsed.get("args").cloned().unwrap_or_else(|| json!({}));
                let replace = parsed["replace"] == true;
                let built = crate::rev2_commands::wire(
                    id,
                    crate::rev2_store::utc(exp),
                    op,
                    &args,
                    replace,
                    crate::rev2_store::utc(args["t"].as_i64().unwrap_or(now)),
                );
                assert_eq!(
                    serde_json::from_str::<Value>(&built).unwrap(),
                    parsed,
                    "{name}"
                );
                envelopes += 1;
                // The server's pre-flight validation agrees with the logger:
                // whatever it rejects as bad-args the server refuses to queue.
                // Deliberate difference: unknown settings keys, which the
                // logger answers `partial`/`unsupported`, are refused too.
                let answer = step["out"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .filter_map(|m| {
                        serde_json::from_str::<Value>(m["payload"].as_str().unwrap()).ok()
                    })
                    .find(|ack| ack["id"].as_i64() == Some(id));
                let reason = answer
                    .as_ref()
                    .and_then(|a| a["reason"].as_str())
                    .unwrap_or("");
                let server = crate::rev2::validate_args(op, &args, now);
                if reason == "bad-args" {
                    assert!(server.is_err(), "{name}: server would queue {text}");
                } else if crate::rev2::kind_of(op).is_some()
                    && !matches!(op, "sync_time" | "confirm")
                    && answer.as_ref().is_some_and(|a| a["status"] != "partial")
                {
                    assert!(server.is_ok(), "{name}: server refuses {text}: {server:?}");
                }
            }
            for message in step["out"].as_array().unwrap() {
                let object =
                    crate::rev2::object(message["payload"].as_str().unwrap().as_bytes()).unwrap();
                crate::rev2::parse_ack(&object).unwrap_or_else(|e| panic!("{name}: {e}"));
            }
        }
    }
    assert!(envelopes > 30);
}
